import{_ as t,c as a,o,a5 as r}from"./chunks/framework.Dl43PoGR.js";const m=JSON.parse('{"title":"F.A.Q","description":"","frontmatter":{"title":"F.A.Q","outline":"deep","prev":{"text":"Volume Profile Tools","link":"/volume-profile-tools"},"next":{"text":"eBooks","link":"/ebooks"}},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),i={name:"faq.md"};function n(s,e,h,l,d,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="f-a-q" tabindex="-1">F.A.Q <a class="header-anchor" href="#f-a-q" aria-label="Permalink to “F.A.Q”">​</a></h1><h2 id="who-are-you" tabindex="-1">Who are you? <a class="header-anchor" href="#who-are-you" aria-label="Permalink to “Who are you?”">​</a></h2><p>Quick Summary – Yogesh Patil, intra-day F&amp;O trader, trading educator, diploma mechanical engineer, husband.</p><p>See the <a href="/team/">Team page</a> for more details.</p><p>Or for another way of answering the question, here’s a bio:</p><blockquote><p>Yogesh Patil is a full time day-trader with a current preference for both BANKNIFTY options and futures. His style of trading is discretionary, operating in the direction of short-term sentiment within a framework of support and resistance.</p></blockquote><blockquote><p>He is the founder and chief contributor to <a href="/">https://ystc-in.github.io/yp</a>, which aims to provide quality trading education and resources with an emphasis on the ‘less sexy’ but more important aspects of trading – business management, risk management, money management and trading psychology.</p></blockquote><h2 id="how-do-you-personally-trade" tabindex="-1">How do you personally trade? <a class="header-anchor" href="#how-do-you-personally-trade" aria-label="Permalink to “How do you personally trade?”">​</a></h2><p>I am a short timeframe discretionary trading, operating in the direction of short-term sentiment within a framework of support and resistance.</p><p>At the moment my trading is primarily in the BANKNIFTY options and to a lesser extent its futures.</p><p>Timeframes are 30 &amp; 15 min for higher timeframe context, 5 &amp; 3 min for the trading timeframe, and a combination of 1 min and 15 sec for lower timeframe fine-tuning.</p><p>The method is a blend of both the YSTC Trading with Price Action Volume.</p><p>For a full description of these trading strategies:</p><ul><li>The <a href="/trading-with-pav-course">YSTC Trading with Price Action Volume</a> outlines the trading strategy that I use on above timeframes mentioned in the BANKNIFTY options and its futures markets. Also commodities.</li></ul><h2 id="if-you-re-so-good-at-trading-why-are-you-teaching" tabindex="-1">If you’re so good at trading, why are you teaching? <a class="header-anchor" href="#if-you-re-so-good-at-trading-why-are-you-teaching" aria-label="Permalink to “If you’re so good at trading, why are you teaching?”">​</a></h2><p>I see this all the time in forums. Trading seems to be the only business in the world (that I know of) in which the public are totally skeptical of anyone who teaches, or shares their methods.</p><p>Perhaps that is very much deserved, given all the rubbish and the hype that exists in the marketplace. It’s unfortunate though. The fact is that there is some real quality information out there amongst the rubbish.</p><p>Hopefully I can help provide some quality. Not all trading educators are a fake.</p><p>Yes, I’m sure many are – I know a few educators personally and seriously doubt some of them trade. However there are others who do trade.</p><p>And yes, it does make me money. Well, at least that’s the plan. I subscribe to the theory of multiple streams of income. I suggest you seriously research this topic as well. Trading should not be your only source of income. Build other income streams – both active and passive.</p><h2 id="there-is-so-much-rubbish-on-the-internet-how-can-i-trust-you" tabindex="-1">There is so much rubbish on the internet? How can I trust you? <a class="header-anchor" href="#there-is-so-much-rubbish-on-the-internet-how-can-i-trust-you" aria-label="Permalink to “There is so much rubbish on the internet? How can I trust you?”">​</a></h2><p>Easy answer – don’t trust me. In fact, don’t trust any trading educator, until they’ve proven themselves worthy of trust. Learn as much as you can from this site.</p><p>The fact that I have my all the course articles <a href="/trading-with-price-action-volume">Trading with Price Action Volume aka VIP Access</a> and my <a href="/posts">posts</a> for free, but don’t put anything into use in a live market until you’ve thoroughly tested it in a demo setting and proven to yourself that it works for you.</p><p>Take what you like from my teachings, and discard the rest. The interesting thing with trading is that what works for me won’t necessarily work for you; but that’s cool. We all trade differently.</p><p>That being said, I’d like to think that the fact that my site is not filled with hype or outrageous promises, allows me to start off with a little credibility.</p><p>In fact, I’ll go so far as to say that trading is possibly going to be the hardest thing you’ve ever tried in your life, and you’ll probably fail. Only a small minority have the patience, courage and determination required to make it.</p><p>Refer to the <a href="/site-map">Site Map</a> for an archive of previous articles or videos to confirm the quality of work meets your standards, and the content meets your needs.</p><h2 id="can-you-teach-me-to-trade" tabindex="-1">Can you teach me to trade? <a class="header-anchor" href="#can-you-teach-me-to-trade" aria-label="Permalink to “Can you teach me to trade?”">​</a></h2><p>If you’re after one-on-one coaching, yes visit here - <a href="/trading-with-pav-course">Trading with PAV Course</a> and if you want demo visit here - <a href="/free-market-webinar">Free Market Introduction</a> where i teach you first two modules of my Trading with PAV Course for Free and if you didn&#39;t like no problem.</p><p>The other teaching I currently do is through this website posts and weekly newsletter for registered users, which provides general information on a wide range of trading topics, and through my self-study VIP Access at <a href="/trading-with-price-action-volume">YSTC Trading with Price Action Volume</a>.</p><p>To be honest though, I don’t think anyone can be taught to trade, at least not the way I trade. Instead it’s something you learn for yourself through experience and immersion in the markets.</p><p>My role in this is to perhaps provide some guidance along the way, keeping you on the right path and minimizing the distractions and false turns. More of a mentor or coach, than teacher. I can point you in the right direction. Success or failure though, is up to you.</p><p>An important factor is whether or not you relate to both my style of teaching and my style of trading. Read some of my articles, watch some of my videos, register to my site to get the weekly newsletter.</p><p>If you like the way I work and if my trading style seems compatible with yours, then perhaps there’s a chance we could work together one day. If you can’t understand my accent or if I speak too quickly, it’s probably not going to work.</p><p>If your underlying beliefs about how markets operate are different from mine, then once again you may be better seeking guidance elsewhere.</p><h2 id="can-you-please-set-up-a-live-trading-room" tabindex="-1">Can you please set up a live trading room? <a class="header-anchor" href="#can-you-please-set-up-a-live-trading-room" aria-label="Permalink to “Can you please set up a live trading room?”">​</a></h2><p>This is unlikely to ever happen. Firstly, my trading environment is a calm, relaxing environment. Usually with some nice background meditation-style music (although sometimes when I’m in a different mood I’ll trade to One Republic, cranked up nice and loud).</p><p>The last thing I imagine I’ll ever want is to be trading with the distractions that come from a live trading room – questions from participants, negativity from the one or two people who seem to be always present in these rooms, disputing or second guessing setups or trade entry or management calls.</p><p>Not to mention the distraction to my trading psychology due to the fact that I’d feel I had to make a profit that session. Trading rooms are not conducive to good trading, at least not for me.</p><p>Secondly, it’d be really boring. I can sit for two hours waiting for the right setup.</p><p>But then you never know what the future may bring. While I am not personally a fan of trading rooms, I do recognize that live trading is a great learning environment. So I will be looking for ways in future to take advantage of these benefits. Perhaps a live classroom or online setting, where you trade and I provide coaching???? Don’t know! More thought required here.</p><h2 id="do-you-do-speaking-engagements" tabindex="-1">Do you do speaking engagements? <a class="header-anchor" href="#do-you-do-speaking-engagements" aria-label="Permalink to “Do you do speaking engagements?”">​</a></h2><p>Sorry – not at the moment. My current priorities are my family, and my own trading and other personal interests. When my lifestyle changes maybe then I’ll have time to do the speaking or trading expo circuit.</p><h2 id="why-so-much-information-for-free-are-you-going-to-be-charging-for-services-later" tabindex="-1">Why so much information for free? Are you going to be charging for services later? <a class="header-anchor" href="#why-so-much-information-for-free-are-you-going-to-be-charging-for-services-later" aria-label="Permalink to “Why so much information for free? Are you going to be charging for services later?”">​</a></h2><p>I intend to continue to offer quality information to all readers, regardless of whether they become paying customers or clients, or not.</p><p>The free information allows us to build a relationship; allows you to confirm the quality of my writing and teaching; and to confirm whether or not my style of teaching and trading suit your needs.</p><p>If you then decide to seek further information through the <a href="/trading-with-pav-course">paid courses</a>, that’s great. If not, that’s fine as well. I hope the free information <a href="/trading-with-price-action-volume">here</a> continues to provide you with great value and assists you on your trader development journey.</p><h2 id="are-you-just-going-to-be-promoting-all-the-latest-price-action-forex-courses-ebooks-or-robots-like-every-other-internet-marketer" tabindex="-1">Are you just going to be promoting all the latest price action, forex courses, eBooks or robots, like every other internet marketer? <a class="header-anchor" href="#are-you-just-going-to-be-promoting-all-the-latest-price-action-forex-courses-ebooks-or-robots-like-every-other-internet-marketer" aria-label="Permalink to “Are you just going to be promoting all the latest price action, forex courses, eBooks or robots, like every other internet marketer?”">​</a></h2><p>I hope not. If I ever start crossing the boundary, let me know &amp; I’ll quit this business.</p><p>The site does have a small number of Google ads and amazon affliates (providing a small contribution for all my time). Ignore them if you don’t like that.</p><p>The resources page and my bookstore will promote various books and resources. However these are currently (and will always be) products, courses, books or resources which I either use myself and have found to be of value, or which are used and recommended by others who I trust. There are very few products that meet this standard.</p><p>You will NOT find me joining the ranks of the internet marketers (most of who don’t trade) in flooding your inbox with a never-ending stream of ‘last system you’ll ever need’ trading eBooks, courses or robots.</p><p>That’s not my game.</p><h2 id="learning-to-trade" tabindex="-1">Learning to Trade: <a class="header-anchor" href="#learning-to-trade" aria-label="Permalink to “Learning to Trade:”">​</a></h2><h2 id="what-s-the-easiest-way-to-learn-to-trade" tabindex="-1">What’s the easiest way to learn to trade? <a class="header-anchor" href="#what-s-the-easiest-way-to-learn-to-trade" aria-label="Permalink to “What’s the easiest way to learn to trade?”">​</a></h2><p>There is no easy way. Like any performance based activity, trading requires considerable work in order to achieve professional levels of competency.<br> What is the best way then?</p><p>Unfortunately, there’s also no best way to learn. The best way for you will depend on your individual personality. Different people learn better through different teaching methods. Some will prefer classroom settings, others will prefer a live trading room. Others will be better just working at their own pace through self-directed learning. This is something I can’t help with – you’ll need to find your own way.</p><p>If you’re interested in discovering how I trade, check out <a href="/trading-with-pav-course">YSTC Trading with PAV Course</a> and Free self taught to course articles <a href="/trading-with-price-action-volume">VIP Access</a>.</p><p>The <a href="/resources">Resources Page</a> lists may also assist, listing the courses and books that I’ve found useful, as well as those recommended by others I trust.</p><p>And be sure to check out all my articles and videos. The quickest way to access them is via the <a href="/site-map">Site Map</a>.</p><h2 id="how-long-does-it-take-to-learn-to-trade" tabindex="-1">How long does it take to learn to trade? <a class="header-anchor" href="#how-long-does-it-take-to-learn-to-trade" aria-label="Permalink to “How long does it take to learn to trade?”">​</a></h2><p>You can learn technical analysis and money management within a few months if you devote sufficient time to the task. However, while that might help you to analyze the market, it doesn’t teach you to trade. Learning to trade is a different matter entirely.</p><p>Learning to trade involves so much more which can’t be taught by any course or book. In particular, the big challenge most traders have is learning to operate in an environment of uncertainty, where your hard earned money is on the line and loss of funds are a very real possibility. You will lose money – losses are a normal occurrence in trading. It takes considerable time to truly learn to accept this risk of loss. A lesson which can only be learnt through experience in the markets.</p><p>It’s impossible to say how long this might take you. It varies from person to person. Typically though, most day-traders take several years. And that’s just the one’s who make it. Given that 95% of people who attempt to trade never actually achieve consistent profitability, then there’s a good chance you’ll never make it. If you want to be part of the 5%, you need to be realistic about the challenges ahead, and prepared to devote several years of your life.</p><p>This is no different to mastering any other performance field.</p><ul><li>How long would it take you to become a professional athlete?</li><li>How long would it take you to become a chess master?</li><li>How long would it take you to become a fluent in other languages?</li><li>How long would it take you to become a professional poker player?</li></ul><h2 id="how-much-money-can-i-make-as-a-trader" tabindex="-1">How much money can I make as a trader? <a class="header-anchor" href="#how-much-money-can-i-make-as-a-trader" aria-label="Permalink to “How much money can I make as a trader?”">​</a></h2><p>There’s actually a higher probability that you’ll lose money, rather than make any. The vast majority of traders consistently lose. The vast majority quit before they ever achieve any degree of consistent profitability. Do NOT get into this business because you need money. Get into it ONLY because you have a passion for the markets and the challenge it offers.</p><p>I also like this quote which I was passed by one of my readers/student,</p><blockquote><p>“If you told a student to spend 3-5 years minimum to qualify in a profession (full time incurring debt along the way) and then flip a coin at the end of it to see if he will be paid a salary on passing – that’s trading!”</p></blockquote><h2 id="how-can-i-get-started" tabindex="-1">How can I get started? <a class="header-anchor" href="#how-can-i-get-started" aria-label="Permalink to “How can I get started?”">​</a></h2><p>If you’re interested in discovering how I trade, check out all course articles self learn for Free <a href="/trading-with-price-action-volume">YSTC Trading with Price Action Volume</a> and <a href="/trading-with-pav-course">YSTC Trading with PAV Course</a>.</p><p>The <a href="/resources">Resources</a> and <a href="/bookstore">Bookstore</a> pages lists may also assist, listing the courses and books that I’ve found useful, as well as those recommended by others I trust.</p><h2 id="what-market-should-i-trade" tabindex="-1">What market should I trade? <a class="header-anchor" href="#what-market-should-i-trade" aria-label="Permalink to “What market should I trade?”">​</a></h2><p>This article here, <a href="/trading-with-pav/market-segments-basics-explained">Market Segments Basics Explained</a>, <a href="/trading-with-pav/finding-your-style">Finding Your Style</a> should hopefully help you with some of the factors you need to consider in making this decision.</p><h2 id="what-timeframe-should-i-trade" tabindex="-1">What timeframe should I trade? <a class="header-anchor" href="#what-timeframe-should-i-trade" aria-label="Permalink to “What timeframe should I trade?”">​</a></h2><p>This article here, <a href="/trading-with-pav/finding-your-style">Finding Your Style</a> and <a href="/trading-with-pav/chart-timeframes">Chart Timeframes</a>, addresses timeframe as well as market selection. It should hopefully help you with some of the factors you need to consider in deciding on a timeframe. Clicking on the link will open the article in a new window.</p><h2 id="can-you-explain-the-trade-markings-on-your-charts" tabindex="-1">Can you explain the trade markings on your charts? <a class="header-anchor" href="#can-you-explain-the-trade-markings-on-your-charts" aria-label="Permalink to “Can you explain the trade markings on your charts?”">​</a></h2><p>See the chart images displayed here for an explanation of all the BUY and SELL markers: <a href="/other/how-trades-are-displayed-on-ytc-charts/">How Trades Are Displayed on YSTC Charts</a></p>',79)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
